import React from "react";

const settings = [
  { title: "Профиль", text: "Имя, аватар, краткое описание" },
  { title: "Приватность", text: "Кто видит посты и список друзей" },
  { title: "Уведомления", text: "Сообщения, лайки и упоминания" },
  { title: "Безопасность", text: "Пароль и активные сессии" },
];

const Settings = () => {
  return (
    <div className="page">
      <div className="pageHeader">
        <div>
          <div className="pageEyebrow">Account</div>
          <h1 className="pageTitle">Настройки</h1>
          <p className="pageSubtitle">Управление аккаунтом и приватностью</p>
        </div>
        <span className="badge">скоро</span>
      </div>

      <div className="grid2">
        {settings.map((item) => (
          <div key={item.title} className="card">
            <strong style={{ display: "block", marginBottom: 6 }}>{item.title}</strong>
            <p style={{ color: "var(--muted)", lineHeight: 1.5 }}>{item.text}</p>
            <div className="feedActions">
              <span className="chip">Открыть позже</span>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default Settings;
